/**
 * Shared CLI handling for structured files generated by app skills.
 * JSON defaults to URL-only results; explicit destinations request a download.
 * Streams into private temporary files and atomically publishes completed bytes.
 * Automatic names use exclusive links; explicit names atomically replace targets.
 * Provider result URLs never receive CLI session credentials from this module.
 * See docs/user-guide/cli/apps-and-skills.md for the command contract.
 */
import {createWriteStream} from 'node:fs';
import {mkdir, link, rename, unlink, stat} from 'node:fs/promises';
import {basename, dirname, extname, resolve} from 'node:path';
import {randomUUID} from 'node:crypto';
import {Readable} from 'node:stream';
import {pipeline} from 'node:stream/promises';

type RecordValue = Record<string, unknown>;
export interface GeneratedFileOptions {enabled: boolean; directory: string; filename?: string; output?: string}
export interface GeneratedFile {url: string; filename: string; assetId?: string}
export interface SavedGeneratedFile {path: string; asset_id?: string}
const DOWNLOAD_TIMEOUT_MS = 5 * 60 * 1000;
const ORIGINAL_VARIANTS = ['original', 'master', 'full'];
const RESULT_FIELDS = ['data', 'result', 'results', 'items', 'final'];
const MIME_EXTENSIONS: Record<string, string> = {'audio/mpeg':'mp3','audio/wav':'wav','image/png':'png','image/jpeg':'jpg','image/webp':'webp','video/mp4':'mp4','application/pdf':'pdf','model/gltf-binary':'glb'};
const record = (value: unknown): RecordValue | undefined => value && typeof value === 'object' && !Array.isArray(value) ? value as RecordValue : undefined;
const text = (value: unknown): string | undefined => typeof value === 'string' && value.length > 0 ? value : undefined;

export function generatedFileOptions(flags: Record<string, string | boolean>, input?: RecordValue): GeneratedFileOptions {
  const option = (name: string): string | undefined => {
    if (flags[name] === undefined) return undefined;
    if (typeof flags[name] !== 'string' || !flags[name].trim()) throw new Error(`--${name} requires a path or name`);
    return flags[name] as string;
  };
  const output = option('output');
  const directory = option('output-dir');
  const filename = option('filename');
  if (output && (directory || filename)) throw new Error('--output cannot be combined with --output-dir or --filename');
  if (filename && (filename !== basename(filename) || /[\\/]/.test(filename) || filename.includes("\0") || filename === '.' || filename === '..')) throw new Error('--filename must be a filename without directories');
  if (flags['no-download'] && (output || directory || filename)) throw new Error('--no-download cannot be combined with download destinations');
  if ((output || filename) && Array.isArray(input?.requests) && input.requests.length > 1) throw new Error('One filename cannot name multiple generated files; use --output-dir');
  return {enabled: !flags['no-download'] && (flags.json !== true || !!(output || directory || filename)), directory: resolve(directory ?? '.'), filename, output: output ? resolve(output) : undefined};
}

function safeName(value: string): string {
  return basename(value.replaceAll('\\','/')).replace(/[^a-zA-Z0-9._-]/g,'_').replace(/^\.+/,'') || 'generated-file';
}

export function collectGeneratedFiles(value: unknown): GeneratedFile[] {
  const files: GeneratedFile[] = [];
  const seen = new Set<string>();
  const add = (meta: RecordValue, parent: RecordValue, variant: string) => {
    const assetId = text(meta.asset_id) ?? text(parent.embed_id) ?? text(parent.asset_id);
    const url = text(meta.download_url) ?? (assetId ? `/v1/embeds/${encodeURIComponent(assetId)}/file?format=${encodeURIComponent(variant)}` : undefined);
    if (!url || seen.has(url)) return;
    seen.add(url);
    const extension = safeName(text(meta.format) ?? MIME_EXTENSIONS[String(meta.mime_type)] ?? variant);
    const suppliedName = text(meta.filename) ?? text(meta.path) ?? text(parent.filename);
    const filename = suppliedName ? safeName(suppliedName) : `openmates-${safeName(assetId ?? 'generated')}.${extension}`;
    files.push({url, filename, assetId});
  };
  const visit = (node: unknown) => {
    if (Array.isArray(node)) {node.forEach(visit); return;}
    const data = record(node);
    if (!data) return;
    const variants = record(data.files);
    if (variants) {
      const entries = Object.entries(variants).filter((entry): entry is [string, RecordValue] => !!record(entry[1]));
      const preferred = [...ORIGINAL_VARIANTS, String(data.output_filetype ?? '')];
      const chosen = preferred.map(key => entries.find(([name]) => name === key)).find(Boolean)
        ?? entries.find(([name]) => !/preview|thumbnail|poster/i.test(name));
      if (chosen) add(chosen[1], data, chosen[0]);
    }
    for (const field of ['artifacts', 'files']) {
      if (Array.isArray(data[field])) for (const item of data[field]) {
        const meta = record(item);
        if (meta && text(meta.download_url)) add(meta, data, text(meta.variant) ?? 'original');
      }
    }
    for (const field of RESULT_FIELDS) if (data[field] !== undefined) visit(data[field]);
  };
  visit(value);
  return files;
}

/** Stream first, then publish: neither interrupted transfers nor collisions destroy existing files. */
export function fetchGeneratedFile(url: string): Promise<Response> {
  return fetch(url, {redirect: "error", signal: AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS)});
}

export async function downloadGeneratedFiles(
  result: unknown,
  options: GeneratedFileOptions,
  fetchFile: (url: string) => Promise<Response> = fetchGeneratedFile,
): Promise<SavedGeneratedFile[]> {
  if (!options.enabled) return [];
  const files = collectGeneratedFiles(result);
  const explicitName = options.output || options.filename;
  if (explicitName && files.length !== 1) throw new Error(`Expected one generated file for the explicit filename; received ${files.length}. Use --output-dir for multiple files.`);
  const saved: SavedGeneratedFile[] = [];
  for (const file of files) {
    let target = options.output ?? resolve(options.directory, options.filename ?? file.filename);
    await mkdir(dirname(target), {recursive:true});
    const temporary = resolve(dirname(target), `.${randomUUID()}.partial`);
    try {
      const response = await fetchFile(file.url);
      if (!response.ok || !response.body) throw new Error(`Download returned HTTP ${response.status}`);
      await pipeline(Readable.fromWeb(response.body as Parameters<typeof Readable.fromWeb>[0]), createWriteStream(temporary, {flags:'wx', mode:0o600}));
      if ((await stat(temporary)).size === 0) throw new Error("Download returned an empty file");
      if (explicitName) await rename(temporary, target);
      else {
        const original = target;
        for (let suffix = 0; ; suffix++) {
          if (suffix) {const extension = extname(original);target = `${original.slice(0, original.length-extension.length)}-${suffix}${extension}`;}
          try {await link(temporary, target);break;}
          catch (error) {if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;}
        }
      }
      saved.push({path:target, asset_id:file.assetId});
    } catch (error) {
      const detail = error instanceof Error && !/https?:/.test(error.message) ? error.message : 'Transfer failed';
      throw new Error(`Generated file download failed (${detail}). Asset: ${file.assetId ?? 'see result'}. Already saved: ${saved.map(f=>f.path).join(', ') || 'none'}. Generation was not retried.`);
    } finally {
      await unlink(temporary).catch(error => {if (error.code !== 'ENOENT') throw error;});
    }
  }
  return saved;
}

export const GENERATED_FILE_HELP = [
  'Generated files:',
  '  By default, save in the current directory with unique automatic names; existing files are preserved.',
  '  --json               Return download URLs and expiry times without downloading, unless a destination is given.',
  '  --output-dir <dir>    Save generated files in this directory (created if missing).',
  '  --filename <name>     Name one output file; replace an existing file after a successful download.',
  '  --output <path>       Full output file path; cannot combine with --output-dir or --filename.',
  '  --no-download        Return results without saving files.',
  '  Examples: --output-dir ./media; --output-dir ./media --filename result.wav; --json --output ./media/result.wav',
].join('\n');
